// The first visit to the map after a build glows; after that the point is
// simply lit. Per device, raw localStorage, like the room's pulse record: it is
// a "have I shown you this here" flag, not progress.
const SEEN_KEY = "tsumiki-journey-seen-v1";
function readSeen() {
  try { const v = JSON.parse(localStorage.getItem(SEEN_KEY) || "[]"); return Array.isArray(v) ? v : []; } catch { return []; }
}
function writeSeen(ids) { try { localStorage.setItem(SEEN_KEY, JSON.stringify(ids)); } catch {} }

