// ————— THE BLOCK. One component: tower, chips, buildings, the detail sheet. —————
const WOODS = ["#C9A47C", "#C59F75", "#CDAA83", "#C29B70", "#CBA67F"];
// A stable 0–1 from the block's id, so the grain is the same on every device.
function grainOf(id) {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) { h ^= id.charCodeAt(i); h = Math.imul(h, 16777619); }
  return ((h >>> 0) % 1000) / 1000;
}
function blockStyle(b, w, h) {
  const g = grainOf(b.id || "x");
  return {
    width: w, height: h, "--r": `${Math.max(2, Math.round(h * 0.16))}px`, "--lipw": `${Math.max(2, Math.round(h * 0.1))}px`,
    ...(b.action === "stage" ? null : { "--wood": WOODS[Math.floor(g * WOODS.length)] }),
    "--grain": `${88 + Math.round(g * 9)}deg`, "--gx": `${Math.round(g * 11)}px`,
  };
}
function Mark({ b, h }) {
  const src = SOURCES[b.source];
  if (!src || b.action === "stage" || b.action === "login") return null;
  const glyph = b.action === "review" ? REVIEW_GLYPH : src.glyph;
  if (!glyph) return null;
  const s = Math.round(h * 0.66);
  return <span className="tj-mk" aria-hidden="true"
               style={{ width: s, height: s, fontSize: Math.round(s * 0.74), backgroundColor: src.accent }}>{glyph}</span>;
}
function Block({ b, w, h, style, className = "", ...rest }) {
  const Tag = rest.onClick ? "button" : "span";
  return (
    <Tag className={"tj-blk" + (b.action === "stage" ? " tj-key" : "") + (className ? " " + className : "")}
         style={{ ...blockStyle(b, w, h), ...style }} data-id={b.id} {...rest}>
      <Mark b={b} h={h} />
    </Tag>
  );
}

export function howEarned(b) {
  const name = SOURCES[b.source]?.name || "";
  switch (b.action) {
    case "lesson": return `Finished a lesson — ${name}`;
    case "review": return `Finished a review — ${name}`;
    case "check":  return "Checked a sentence";
    case "login":  return "Showed up";
    case "stage":  return `Finished ${b.label || "a stage"}`;
    default:       return name;
  }
}

// ————— The tower's shape —————
// Rows alternate a full course and one a block shorter (running bond), and the
// tower narrows every few courses. The base grows with the pile — "widens when
// it needs to". Blocks are laid oldest first, so the foundation is the early
// kana and the first days of showing up.
export function towerShape(n) {
  if (!n) return { pos: [], W: 0, rows: 0 };
  const W = n <= 3 ? n : Math.max(3, Math.min(12, Math.ceil(Math.sqrt(n * 0.55))));
  const pos = []; let row = 0, placed = 0;
  while (placed < n) {
    const wide = Math.max(Math.ceil(W * 0.5), W - Math.floor(row / 5));
    const width = Math.max(1, row % 2 === 0 ? wide : wide - 1);
    const k = Math.min(width, n - placed);
    for (let i = 0; i < k; i++) pos.push({ x: (W - k) / 2 + i, y: row });
    placed += k; row++;
  }
  return { pos, W, rows: row };
}

function useWidth(ref) {
  const [w, setW] = useState(0);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const read = () => setW(el.clientWidth);
    read();
    let ro = null;
    try { ro = new ResizeObserver(read); ro.observe(el); } catch { window.addEventListener("resize", read); }
    return () => { if (ro) ro.disconnect(); else window.removeEventListener("resize", read); };
  }, [ref]);
  return w;
}

function Tower({ blocks, filter, onOpen }) {
  const ref = useRef(null);
  const sw = useWidth(ref) || 358;
  const { pos, W, rows } = towerShape(blocks.length);
  const PLANK = 14;
  const bw = W ? Math.min(40, Math.floor((sw - 28) / W)) : 0, bh = Math.round(bw * 0.66);
  const x0 = (sw - W * bw) / 2;
  const hit = (b) => filter === "review" ? b.action === "review" : b.source === filter;
  return (
    <div ref={ref} className="tj-tower" style={{ position: "relative", margin: "0 -16px", flex: "1 0 auto",
      minHeight: 220, height: blocks.length ? rows * bh + PLANK + 28 : 220 }}>
      <div className="tj-plank" />
      {blocks.map((b, i) => {
        const on = filter && hit(b);
        return (
          <Block key={b.id} b={b} w={bw - 2} h={bh - 3}
                 className={on ? "tj-lit" : filter ? "tj-dim" : ""}
                 style={{ left: x0 + pos[i].x * bw + 1, bottom: PLANK + pos[i].y * bh + 1 }}
                 aria-label={`${howEarned(b)}, ${whenOf(b)}`}
                 onClick={() => onOpen(b)} />
        );
      })}
    </div>
  );
}

function MapSvg({ built, inset, firstGlow, onPoint }) {
  return (
    <svg viewBox={`0 0 ${MAP_W} ${MAP_H}`} style={{ display: "block", width: "100%", height: "auto" }}
         role="img" aria-label={built.length ? "Map of Japan showing the places you've built" : "Map of Japan"}>
      <rect width={MAP_W} height={MAP_H} rx="10" fill="#F4EEDF" />
      <path className="tj-land" d={JAPAN_D} />
      {built.map((id) => {
        const r = RECIPES[id];
        if (!r) return null;
        const p = r.place;
        if (inset) return <circle key={id} cx={p.x} cy={p.y} r="9" fill="#C9A24A" stroke="#7A5A3C" strokeWidth="3" />;
        const below = p.label === "below";
        return (
          <g key={id} className={"tj-pt" + (firstGlow.includes(id) ? " tj-first" : "")} role="button" tabIndex={0}
             aria-label={`${r.en} at ${p.en}`}
             onClick={() => onPoint(id)}
             onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onPoint(id); } }}>
            <circle cx={p.x} cy={p.y} r="22" fill="transparent" />
            <circle className="tj-halo" cx={p.x} cy={p.y} r="11" />
            <circle className="tj-dot" cx={p.x} cy={p.y} r="6" />
            {below ? (<>
              <text x={p.x} y={p.y + 26} textAnchor="middle">{p.jp}</text>
              <text className="tj-rd" x={p.x} y={p.y + 41} textAnchor="middle">{p.kana}</text>
            </>) : (<>
              <text x={p.x + 12} y={p.y - 22}>{p.jp}</text>
              <text className="tj-rd" x={p.x + 12} y={p.y - 8}>{p.kana}</text>
            </>)}
          </g>
        );
      })}
    </svg>
  );
}

// A building, drawn from the learner's own blocks.
function Building({ id, blocks, maxW, innerRef }) {
  const a = assignForBuilding(id, blocks);
  const cw = Math.min(34, Math.floor(maxW / a.cols)), ch = Math.round(cw * 0.66);
  return (
    <div ref={innerRef} style={{ position: "relative", width: a.cols * cw, height: a.rows * ch + 4 }}
         role="img" aria-label={`A ${RECIPES[id].en}, made of your blocks`}>
      {a.slots.map((s) => (
        <Block key={s.x + "," + s.y} b={s.b} w={cw - 2} h={ch - 3}
               style={{ left: s.x * cw + 1, top: s.y * ch + 1, cursor: "default" }} data-slot={s.x + "," + s.y} />
      ))}
    </div>
  );
}

// The reading sits on its OWN LINE above the kanji, at a size a learner still
// sounding out kana can read — not as <rt> furigana at half size (Lloyd, Oct 6).
function Names({ r }) {
  const reading = (kana, size) => (
    <span lang="ja" style={{ display: "block", font: `${size} ${T.jpFont}`, lineHeight: 1.3, color: T.sub }}>{kana}</span>
  );
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
        {reading(r.kana, "0.9375rem")}
        <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
          <span lang="ja" style={{ font: `700 1.5rem/1.2 ${T.jpFont}` }}>{r.jp}</span>
          <span style={{ font: `700 0.9375rem ${T.uiFont}` }}>A {r.en}</span>
        </div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
        {reading(r.place.kana, "0.875rem")}
        <div style={{ display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap", font: `0.875rem ${T.uiFont}`, color: T.sub }}>
          <span lang="ja" style={{ font: `1.0625rem/1.3 ${T.jpFont}`, color: T.ink }}>{r.place.jp}</span>
          <span>{r.place.en}</span>
        </div>
      </div>
    </div>
  );
}

function Sheet({ onClose, children }) {
  const closeRef = useRef(null);
  useEffect(() => {
    closeRef.current?.focus({ preventScroll: true });
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [onClose]);
  return (
    <>
      <div className="tj-scrim" onClick={onClose} aria-hidden="true" />
      <div className="ts-washi-tex tj-sheet" role="dialog" aria-modal="true">
        {children}
        <button ref={closeRef} className="ts-btn ts-btn-washi" onClick={onClose}>Close</button>
      </div>
    </>
  );
}

function BlockSheet({ b, onClose }) {
  return (
    <Sheet onClose={onClose}>
      <div style={{ display: "flex", gap: 16, alignItems: "center" }}>
        <Block b={b} w={84} h={56} style={{ position: "relative", flexShrink: 0, cursor: "default" }} />
        <div style={{ display: "flex", flexDirection: "column", gap: 4, minWidth: 0 }}>
          <h3 style={{ margin: 0, font: `700 1.1875rem/1.3 ${T.uiFont}` }}>{howEarned(b)}</h3>
          <span style={{ font: `0.8125rem ${T.uiFont}`, color: T.sub }}>{whenOf(b)}</span>
          {b.action === "lesson" && b.label && (
            <span lang="ja" style={{ font: `600 1.0625rem ${T.jpFont}` }}>{b.label}</span>
          )}
        </div>
      </div>
      {b.action === "check" && b.sentence && (<>
        {/* AS WRITTEN. No verdict, no underline, no correction — the block is
            effort, and this is the sentence that earned it. */}
        <div className="ts-inset" lang="ja" style={{ font: `1.25rem/1.7 ${T.jpFont}` }}>{b.sentence}</div>
        <span style={{ font: `0.8125rem ${T.uiFont}`, color: T.sub }}>Kept just as you wrote it.</span>
      </>)}
      {b.action === "stage" && (
        <span style={{ font: `0.8125rem ${T.uiFont}`, color: T.sub }}>Laid with the others from the same stage, all on one day.</span>
      )}
    </Sheet>
  );
}

function BuildingSheet({ id, blocks, onClose }) {
  return (
    <Sheet onClose={onClose}>
      <Names r={RECIPES[id]} />
      <div style={{ display: "flex", justifyContent: "center", padding: "6px 0 4px" }}>
        <Building id={id} blocks={blocks} maxW={Math.min(300, (typeof window !== "undefined" ? window.innerWidth : 360) - 60)} />
      </div>
    </Sheet>
  );
}

// ————— The build moment —————
// Copies of the learner's blocks lift from the tower and assemble. THE TOWER'S
// OWN BLOCKS NEVER MOVE: the tower is the all-time pile and buildings are made
// FROM it — a block appears in both, because it is data. Reduced motion skips
// straight to the finished building with a short crossfade.
function BuildOverlay({ id, blocks, onDone }) {
  const wrapRef = useRef(null);
  const goRef = useRef(null);
  const [on, setOn] = useState(false);
  const [done, setDone] = useState(false);
  const reduced = useRef(reducedMotion()).current;

  useEffect(() => {
    markBuilt(id);
    if (reduced) { setOn(true); setDone(true); return undefined; }
    const flyers = [];
    const raf = requestAnimationFrame(() => {
      setOn(true);
      const wrap = wrapRef.current;
      if (!wrap) { setDone(true); return; }
      const wr = wrap.getBoundingClientRect();
      const slots = [...wrap.querySelectorAll("[data-slot]")];
      // bottom-up, so it assembles from the ground
      slots.sort((p, q) => q.getBoundingClientRect().top - p.getBoundingClientRect().top || p.getBoundingClientRect().left - q.getBoundingClientRect().left);
      let last = null;
      slots.forEach((slot, i) => {
        const tr = slot.getBoundingClientRect();
        const src = document.querySelector(`.tj-tower .tj-blk[data-id="${CSS.escape(slot.dataset.id)}"]`);
        const fly = slot.cloneNode(true);
        fly.classList.add("tj-fly");
        fly.removeAttribute("data-slot");
        fly.style.left = "0px"; fly.style.top = "0px";
        document.body.appendChild(fly);
        flyers.push(fly);
        let from = `translate(${tr.left}px,${window.innerHeight + 40}px)`, lift = from;
        const sr = src && src.getBoundingClientRect();
        if (sr && sr.width) {
          const sc = sr.width / tr.width;
          from = `translate(${sr.left}px,${sr.top}px) scale(${sc})`;
          lift = `translate(${sr.left}px,${sr.top - 26}px) scale(${sc * 1.1})`;
        }
        last = fly.animate([
          { transform: from, offset: 0 },
          { transform: lift, offset: 0.25 },
          { transform: `translate(${tr.left}px,${tr.top - 10}px) scale(1.04)`, offset: 0.85 },
          { transform: `translate(${tr.left}px,${tr.top}px) scale(1)`, offset: 1 },
        ], { duration: 950, delay: i * 32, easing: "cubic-bezier(.45,.05,.3,1)", fill: "both" });
      });
      void wr;
      if (last) last.onfinish = () => { flyers.forEach((f) => f.remove()); setDone(true); };
      else setDone(true);
    });
    return () => { cancelAnimationFrame(raf); flyers.forEach((f) => f.remove()); };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => { if (done) goRef.current?.focus({ preventScroll: true }); }, [done]);

  return (
    <div className={"tj-build" + (on ? " tj-on" : "") + (reduced ? " tj-fade" : "")} role="dialog" aria-modal="true"
         aria-label={`Building a ${RECIPES[id].en}`}>
      <div style={{ flex: 1, display: "flex", alignItems: "flex-end", justifyContent: "center", padding: "0 16px 22px" }}>
        <div style={{ visibility: done ? "visible" : "hidden" }}>
          <Building id={id} blocks={blocks} innerRef={wrapRef}
                    maxW={Math.min(380, (typeof window !== "undefined" ? window.innerWidth : 360) - 40)} />
        </div>
      </div>
      {done && (
        <div className="ts-card tj-cap" style={{ margin: "0 auto 20px", width: "calc(100% - 32px)", maxWidth: 488,
             boxSizing: "border-box", padding: "16px 18px", display: "flex", flexDirection: "column", gap: 10 }}>
          <span style={LABEL}>BUILT FROM YOUR BLOCKS</span>
          <Names r={RECIPES[id]} />
          <span style={{ font: `0.8125rem ${T.uiFont}`, color: T.sub }}>Your tower is just as it was.</span>
          <button ref={goRef} className="ts-btn ts-btn-shu" onClick={onDone}>See it on your map</button>
        </div>
      )}
    </div>
  );
}

// ————— The screen —————
export default function Journey() {
  const [led, setLed] = useState(null);         // { blocks, built }
  const [view, setView] = useState("tower");
  const [filter, setFilter] = useState(null);
  const [openBlock, setOpenBlock] = useState(null);
  const [openBuilding, setOpenBuilding] = useState(null);
  const [building, setBuilding] = useState(null);
  const [firstGlow, setFirstGlow] = useState([]);

  const load = useCallback(async () => {
    try { await reconcileBlocks(); } catch (e) { console.error("blocks reconcile failed", e); }
    setLed(await readBlocks());
  }, []);
  useEffect(() => { load(); }, [load]);

  if (!led) return <p style={{ padding: "40px 18px", color: T.sub, font: `0.875rem ${T.uiFont}` }}>Loading…</p>;

  const blocks = led.blocks;
  const built = Object.keys(led.built || {}).filter((id) => RECIPES[id])
    .sort((a, b) => led.built[a] - led.built[b]);
  const pending = earnedUnbuilt(blocks, led.built);

  const openMap = (ids = built) => {
    // The first visit after a build glows; mark it seen here so the next is simply lit.
    const seen = readSeen();
    setFirstGlow(ids.filter((id) => !seen.includes(id)));
    writeSeen([...new Set([...seen, ...ids])]);
    setView("map");
    window.scrollTo({ top: 0 });
  };

  const kinds = [];
  for (const s of ["hiragana", "katakana", "kanji", "grammar", "vocabulary", "checker"])
    if (blocks.some((b) => b.source === s)) kinds.push({ key: s, name: SOURCES[s].name, sample: { id: "chip-" + s, source: s, action: s === "checker" ? "check" : "lesson" } });
  if (blocks.some((b) => b.action === "review")) kinds.push({ key: "review", name: "Reviews", sample: { id: "chip-review", source: "grammar", action: "review" } });
  if (blocks.some((b) => b.source === "login")) kinds.push({ key: "login", name: "Showing up", sample: { id: "chip-login", source: "login", action: "login" } });
  if (blocks.some((b) => b.source === "stage")) kinds.push({ key: "stage", name: "Stages", sample: { id: "chip-stage", source: "stage", action: "stage" } });

  const quiet = { margin: 0, font: `0.875rem/1.6 ${T.uiFont}`, color: "var(--ts-on-tatami)" };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14, padding: "16px 16px 0", minHeight: "calc(100vh - 56px)", boxSizing: "border-box" }}>
      <style>{JOURNEY_CSS}</style>
      {view === "map" ? (<>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <span style={{ ...LABEL, color: "var(--ts-on-tatami)" }}>YOUR TSUMIKI JOURNEY</span>
          <span style={{ font: `0.8125rem ${T.jpFont}`, color: "var(--ts-on-tatami)" }}>つみき</span>
        </div>
        <div className="ts-card" style={{ padding: 10, display: "flex", flexDirection: "column", gap: 6 }}>
          <MapSvg built={built} firstGlow={firstGlow} onPoint={setOpenBuilding} />
          {!built.length && (
            <p style={{ margin: 0, textAlign: "center", padding: "4px 8px 6px", font: `0.875rem/1.6 ${T.uiFont}`, color: T.sub }}>
              Your journey starts with your first blocks.
            </p>
          )}
        </div>
        <button className="ts-btn ts-btn-washi" style={{ alignSelf: "center", marginBottom: 20 }}
                onClick={() => { setView("tower"); setFirstGlow([]); }}>Back to your tower</button>
      </>) : (<>
        <div style={{ display: "flex", gap: 12, alignItems: "stretch" }}>
          <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", gap: 10, justifyContent: "flex-end" }}>
            {!blocks.length ? (
              <p style={quiet}>Every lesson you finish, and the days you show up, lay blocks here.</p>
            ) : pending ? (
              <div className="ts-card" style={{ padding: "14px 16px", display: "flex", flexDirection: "column", gap: 10 }}>
                <span style={LABEL}>FROM YOUR BLOCKS</span>
                <div style={{ font: `700 1.125rem/1.35 ${T.uiFont}` }}>You've gathered enough for {RECIPES[pending].announce}.</div>
                <button className="ts-btn ts-btn-shu" onClick={() => setBuilding(pending)}>Build</button>
              </div>
            ) : (
              <p style={quiet}>Everything you've done here, laid one block at a time.</p>
            )}
          </div>
          <button className="ts-card ts-card-btn" onClick={() => openMap()} aria-label="Open your map"
                  style={{ width: 112, flexShrink: 0, padding: "6px 6px 4px", alignItems: "stretch", gap: 2 }}>
            <MapSvg built={built} inset firstGlow={[]} onPoint={() => {}} />
            <span style={{ ...LABEL, fontSize: "0.625rem", textAlign: "center" }}>MAP</span>
          </button>
        </div>

        {blocks.length > 0 && (
          <div className="tj-chips" role="group" aria-label="Show blocks from">
            {kinds.map((k) => (
              <button key={k.key} className="tj-chip" aria-pressed={filter === k.key}
                      onClick={() => setFilter((f) => (f === k.key ? null : k.key))}>
                <Block b={k.sample} w={30} h={20} style={{ position: "relative" }} aria-hidden="true" />
                {k.name}
              </button>
            ))}
          </div>
        )}

        <Tower blocks={blocks} filter={filter} onOpen={setOpenBlock} />
      </>)}

      {openBlock && <BlockSheet b={openBlock} onClose={() => setOpenBlock(null)} />}
      {openBuilding && <BuildingSheet id={openBuilding} blocks={blocks} onClose={() => setOpenBuilding(null)} />}
      {building && (
        <BuildOverlay id={building} blocks={blocks}
                      onDone={async () => {
                        const next = await readBlocks();
                        setBuilding(null); setLed(next);
                        openMap(Object.keys(next.built || {}).filter((k) => RECIPES[k]));
                      }} />
      )}
    </div>
  );
}
